-- Yönetim paneli D1 şeması (idealist-panel). Üretimdeki şemanın birebir kopyası (15.10.2026, sqlite_master'dan).
CREATE TABLE IF NOT EXISTS belge_ek (id INTEGER PRIMARY KEY AUTOINCREMENT, kid TEXT NOT NULL, grup TEXT NOT NULL DEFAULT '', yil TEXT NOT NULL, etiket TEXT NOT NULL, etiket_en TEXT NOT NULL DEFAULT '', anahtar TEXT NOT NULL UNIQUE, dosya_adi TEXT NOT NULL, boyut INTEGER NOT NULL, sha256 TEXT NOT NULL, sira INTEGER NOT NULL DEFAULT 0, yayinda INTEGER NOT NULL DEFAULT 1, olusturan TEXT NOT NULL, olusturma TEXT NOT NULL DEFAULT (datetime('now')), guncelleme TEXT, hedef TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS haber_ek (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, baslik TEXT NOT NULL, tarih TEXT NOT NULL, govde TEXT NOT NULL, ekler TEXT NOT NULL DEFAULT '[]', yayinda INTEGER NOT NULL DEFAULT 1, olusturan TEXT NOT NULL, olusturma TEXT NOT NULL DEFAULT (datetime('now')), guncelleme TEXT);
CREATE TABLE IF NOT EXISTS giris_kodu (email TEXT PRIMARY KEY, kod_ozet TEXT NOT NULL, bitis INTEGER NOT NULL, deneme INTEGER NOT NULL DEFAULT 0, gonderim INTEGER NOT NULL DEFAULT 0, pencere INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS oturum (ozet TEXT PRIMARY KEY, email TEXT NOT NULL, bitis INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meta (anahtar TEXT PRIMARY KEY, deger TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS islem_kaydi (id INTEGER PRIMARY KEY AUTOINCREMENT, zaman TEXT NOT NULL DEFAULT (datetime('now')), email TEXT NOT NULL, islem TEXT NOT NULL, ayrinti TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO meta (anahtar, deger) VALUES ('surum', '1');
